export default function handler(req, res) {
  res.json({ from: 'auth' })
}

export async function action() {
  'use cache'
  return 'first'
}

export async function action() {
  'use server'
  return 'first'
}

'use client'

import { redirectToOtherDeployment } from './redirect-action'

export function ActionRedirectButton() {
  return (
    <form action={redirectToOtherDeployment}>
      <button id="redirect-action-button" type="submit">
        Redirect via Server Action
      </button>
    </form>
  )
}

'use server'

import { redirect } from 'next/navigation'

export async function redirectToOtherDeployment() {
  // Redirect to the dynamic page on deployment 2
  redirect('/dynamic-page?deployment=2')
}

import { redirect } from 'next/navigation'

async function redirectToOtherDeployment() {
  'use server'
  // Route the redirect prefetch back through the test proxy so the action
  // response can come from deployment 2 instead of the current worker.
  if (process.env.TEST_PROXY_ORIGIN) {
    process.env.__NEXT_PRIVATE_ORIGIN = process.env.TEST_PROXY_ORIGIN
  }
  redirect('/dynamic-page?deployment=2')
}

export default function ActionRedirectPage() {
  return (
    <div>
      <h1 id="action-page">Action Redirect Page</h1>
      <form action={redirectToOtherDeployment}>
        <button id="redirect-action-button" type="submit">
          Redirect via Server Action
        </button>
      </form>
    </div>
  )
}

import Client from './client'

export default function Page() {
  return <Client />
}

'use client'

import { useState } from 'react'
import { readCachedValue } from './action'

export default function Client() {
  const [value, setValue] = useState('')
  return (
    <>
      <button
        id="run-action"
        onClick={async () => setValue(await readCachedValue())}
      >
        Read cached value
      </button>
      <p id="action-data">{value}</p>
    </>
  )
}

'use server'

import { getGeneratorValue } from '../../generator-value'

export async function readCachedValue() {
  return getGeneratorValue('action')
}

export function normalize(value: string) {
  return value.toLowerCase()
}

import { randomUUID } from 'node:crypto'
import { normalize } from './normalize'

export function getValue() {
  return randomUUID()
}

// Only the page uses this export, so the normalizer's import edge is unused
// in the route handler. This must not change the cached function's code hash.
export function getKind() {
  return normalize('PAGE-API')
}

import { revalidatePath, revalidateTag } from 'next/cache'

export async function POST(request: Request) {
  const { searchParams } = new URL(request.url)
  const path = searchParams.get('path')
  const tag = searchParams.get('tag')

  if (path) {
    revalidatePath(path)
  }
  if (tag) {
    revalidateTag(tag, 'max')
  }

  return Response.json({ ok: true, path, tag })
}

import { cacheLife } from 'next/cache'
import { getValue } from './server-api'

export async function getPageApiValue(kind: string) {
  'use cache: remote'
  cacheLife('days')

  return getValue()
}

import { connection } from 'next/server'
import { getUrl } from './get-url'

export default async function Page() {
  await connection()
  return <p id="page-api-url">{await getUrl()}</p>
}

import { cacheLife } from 'next/cache'

export async function getUrl() {
  'use cache: remote'
  cacheLife('days')

  const url = new URL('./asset.txt', import.meta.url)
  return url.toString()
}

import { connection } from 'next/server'
import { getUrl } from '../get-url'

export async function GET() {
  await connection()
  return new Response(await getUrl())
}

import { connection } from 'next/server'
import { getPageApiValue } from '../get-value'

export async function GET() {
  await connection()
  return new Response(await getPageApiValue('page-api'))
}

